import socket

DESTINATION_HOST = "sv1.ipopkorea.com"
DESTINATION_PORT = 2301

message = "UDP test message"

sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
sock.sendto(message.encode("utf-8"), (DESTINATION_HOST, DESTINATION_PORT))
# sock.close()

print("Message sent.")

# ▶ 서버 응답 수신
sock.settimeout(5.0)  # 응답 대기 시간 (초)

try:
    data, addr = sock.recvfrom(65535)
    print(f"[클라이언트] 서버 응답 수신: {data.decode('utf-8')}")
    print(f"[클라이언트] 서버 주소: {addr}")
except socket.timeout:
    print("[클라이언트] 서버 응답 없음 (타임아웃)")